sp_widget.client_script:
api.controller = function($scope, $location, $window) {
  var c = this;
  c.tab = 'overview'; // Default tab

  c.applyForGrant = function() {
    // Navigate to application page
    $window.location.href = '?id=grant_application&program_id=' + ($scope.data.program && $scope.data.program.sys_id);
  };

  c.goBack = function() {
    $window.history.back();
  };
};

sp_widget.css:
.grant-detail-page {
  background: #f5f7fa;
  min-height: 100vh;

  // Hero Section - CLEAN IMAGE ONLY
  .hero-section {
    width: 100%;
    height: 320px;
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    position: relative;

    .hero-overlay {
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: linear-gradient(180deg, rgba(0,0,0,0) 0%, rgba(0,0,0,0.25) 100%);
    }
  }

  // Simple Hero (No Image)
  .hero-section-simple {
    width: 100%;
    height: 80px;
    background: linear-gradient(135deg, #1e3a8a 0%, #3b82f6 100%);
  }

  // Main Content
  .detail-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 32px 40px 60px;
    position: relative;
  }

  // Program Title (NO BREADCRUMB)
  .program-title {
    font-size: 2.6rem;
    font-weight: 800;
    color: #1f2937;
    margin: 0 0 16px 0;
    line-height: 1.2;
  }

  // Status Badges
  .status-badges {
    display: flex;
    gap: 12px;
    margin-bottom: 32px;
    flex-wrap: wrap;

    .status-badge, .active-badge {
      padding: 6px 16px;
      border-radius: 20px;
      font-size: 0.9em;
      font-weight: 600;
      background: #e5e7eb;
      color: #6b7280;

      &.published {
        background: #d1fae5;
        color: #059669;
      }
    }

    .active-badge {
      background: #dbeafe;
      color: #2563eb;

      i {
        margin-right: 4px;
      }
    }
  }

  // Quick Info Grid
  .quick-info-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 20px;
    margin-bottom: 40px;
  }

  .info-card {
    background: #fff;
    border-radius: 12px;
    padding: 24px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06);
    border: 1px solid #e5e7eb;
    display: flex;
    align-items: center;
    gap: 16px;
    transition: all 0.3s;

    &:hover {
      box-shadow: 0 8px 24px rgba(0,0,0,0.1);
      transform: translateY(-2px);
    }

    .info-icon {
      width: 50px;
      height: 50px;
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.5em;
      flex-shrink: 0;

      &.budget-icon {
        background: linear-gradient(135deg, #10b981 0%, #059669 100%);
        color: #fff;
      }
      &.date-icon {
        background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%);
        color: #fff;
      }
      &.close-icon {
        background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
        color: #fff;
      }
      &.category-icon {
        background: linear-gradient(135deg, #8b5cf6 0%, #7c3aed 100%);
        color: #fff;
      }
    }

    .info-content {
      display: flex;
      flex-direction: column;
      gap: 4px;

      .info-label {
        font-size: 0.85em;
        color: #6b7280;
        font-weight: 500;
        text-transform: uppercase;
        letter-spacing: 0.05em;
      }

      .info-value {
        font-size: 1.15em;
        font-weight: 700;
        color: #1f2937;
      }
    }
  }

  // Tabs
  .tabs-nav {
    display: flex;
    gap: 8px;
    background: #fff;
    border-radius: 12px;
    padding: 8px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06);
    margin-bottom: 24px;
    flex-wrap: wrap;
  }

  .tab-btn {
    flex: 1;
    min-width: 150px;
    padding: 12px 20px;
    border: none;
    background: transparent;
    color: #6b7280;
    font-size: 0.95em;
    font-weight: 600;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.3s;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;

    i {
      font-size: 1.1em;
    }

    &:hover {
      background: #f3f4f6;
      color: #1f2937;
    }

    &.active {
      background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%);
      color: #fff;
      box-shadow: 0 4px 12px rgba(59,130,246,0.3);
    }
  }

  // Tab Content
  .tab-content {
    background: #fff;
    border-radius: 12px;
    padding: 32px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.06);
    margin-bottom: 32px;
  }

  .tab-panel {
    animation: fadeIn 0.3s ease-in;
  }

  @keyframes fadeIn {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
  }

  .content-section {
    margin-bottom: 32px;

    &:last-child {
      margin-bottom: 0;
    }
  }

  .section-title {
    font-size: 1.35em;
    font-weight: 700;
    color: #1f2937;
    margin-bottom: 20px;
    display: flex;
    align-items: center;
    gap: 10px;
    padding-bottom: 12px;
    border-bottom: 2px solid #e5e7eb;

    i {
      color: #3b82f6;
      font-size: 0.9em;
    }
  }

  .field-group {
    display: flex;
    flex-direction: column;
    gap: 16px;
  }

  .field-row {
    display: grid;
    grid-template-columns: 200px 1fr;
    gap: 20px;
    align-items: start;
    padding: 12px 0;
    border-bottom: 1px solid #f3f4f6;

    &:last-child {
      border-bottom: none;
    }

    .field-label {
      font-weight: 600;
      color: #6b7280;
      font-size: 0.95em;
    }

    .field-value {
      color: #1f2937;
      font-weight: 500;

      &.highlight {
        color: #059669;
        font-size: 1.15em;
        font-weight: 700;
      }
    }
  }

  .description-text {
    color: #4b5563;
    font-size: 1.02em;
    line-height: 1.7;
    margin: 0;
  }

  // Action Section
  .action-section {
    display: flex;
    justify-content: center;
  }

  .back-btn {
    padding: 14px 32px;
    border-radius: 10px;
    font-size: 1.05em;
    font-weight: 600;
    cursor: pointer;
    border: 2px solid #e5e7eb;
    background: #fff;
    color: #6b7280;
    display: flex;
    align-items: center;
    gap: 10px;
    transition: all 0.3s;

    i {
      font-size: 1.1em;
    }

    &:hover {
      background: #f9fafb;
      border-color: #d1d5db;
      color: #1f2937;
      transform: translateX(-4px);
    }
  }

  // Loading & Error States
  .loading-state, .error-state {
    text-align: center;
    padding: 100px 20px;

    i {
      font-size: 3em;
      color: #3b82f6;
      margin-bottom: 20px;
      display: block;
    }

    p {
      font-size: 1.2em;
      color: #6b7280;
      margin-bottom: 24px;
    }
  }

  .error-state i {
    color: #ef4444;
  }

  // Responsive
  @media (max-width: 768px) {
    .hero-section {
      height: 240px;
    }

    .detail-container {
      padding: 24px 20px 40px;
    }

    .program-title {
      font-size: 2em;
    }

    .quick-info-grid {
      grid-template-columns: 1fr;
    }

    .tab-content {
      padding: 20px;
    }

    .field-row {
      grid-template-columns: 1fr;
      gap: 8px;
    }

    .tabs-nav {
      flex-direction: column;
    }

    .tab-btn {
      min-width: auto;
    }
  }
}

sp_widget.script:
(function() {
  data.loaded = false;
  data.program = null;

  // --- For Service Portal, get param from 'input', for Workspace from 'options', also try gs.action.getGlideURI()
  var programId =
     (input && input.program_id)
     || (options && options.program_id)
     || (function() {
           var url = gs.action.getGlideURI ? gs.action.getGlideURI() : null;
           if (url) {
             return url.get('program_id');
           }
           // Try old-fashioned parsing
           var qs = '' + (gs.request && gs.request.getQueryString() ? gs.request.getQueryString() : '');
           var match = qs.match(/program_id=([^&]*)/);
           return match ? match[1] : '';
        })();

  if (!programId) return; // Defensive: fail quietly if nothing found

  // Now get the program record
  var gr = new GlideRecordSecure('x_enno_gatenow_grant_program');
  if (gr.get(programId)) {
var budgetDisplay = gr.getDisplayValue('program_budget')
    data.program = {
      number: gr.getValue('number'),
      name: gr.getValue('program_name'),
      lead: gr.getDisplayValue('program_lead'),
      manager: gr.getDisplayValue('program_manager'),
      status: gr.getDisplayValue('status'),
      active: gr.getValue('active') == '1' || gr.getValue('active') == true,
      start_date: gr.getDisplayValue('start_date'),
      end_date: gr.getDisplayValue('end_date'),
      proposal_open: gr.getDisplayValue('proposal_open_date'),
      proposal_close: gr.getDisplayValue('proposal_close_date'),
      priority: gr.getDisplayValue('priority'),
      announcement: gr.getValue('announcement'),
      budget: budgetDisplay,

      disbursement_schedule: gr.getDisplayValue('disbursement_schedule'),
      disbursement_type: gr.getDisplayValue('disbursement_type'),
      category: gr.getDisplayValue('category'),
      award_type: gr.getDisplayValue('award_type'),
      description: gr.getValue('description'),
      image: gr.getDisplayValue('image'),
      synopsis: gr.getValue('synopsis'),
      summary_statement: gr.getValue('summary_statement'),
      eligibility_summary: gr.getValue('eligibility_summary'),
      terms: gr.getValue('terms_and_conditions'),
      work_notes: gr.getValue('work_notes')
    };
    data.loaded = true;
  }
})();
